    if t in ('Patient',): continue
    for r in R[t]:
        p=subj(r)
        if p: bypat[p].append(r)
for p in bypat: bypat[p].sort(key=lambda r:(et(r) or r.get('period',{}).get('start','') or r.get('authoredOn','')))
pats={p['id']:p for p in R['Patient']}
eps=collections.defaultdict(list)
