        W('  DOC %s [%s] %s %s role=%s'%(d['id'],d['type']['text'],d.get('date','')[:10],[a['display'] for a in d.get('author',[])],ext(d,'author-role')))
        W('    | '+d['description'].replace('\n','\n    | '))
    for t in [r for r in bypat[pid] if r['resourceType']=='Task']:
        W('  REQUEST %s %s %s :: %s'%(t['id'],t['code']['coding'][0]['code'],t['focus']['reference'],t['description']))
open('/tmp/a/anal.txt','w').write('\n'.join(lines))
print(len(lines))
